/*insertMasterMdCmCmsBuyInfoReg*/
INSERT INTO CMSPRICE
(
	  CMS_CATLG_ID, CATLG_SEQ, STATUS
	, ADD_USER_ID, ADD_DATE, ADD_TIME
	, AGENT, BUY_PRICE, PROCESS_TYPE, DELIVERY_TYPE, DELIVERY_LT
	, MIN_ORDER_QTY, PUR_UNIT_QTY, BUY_OPEN_DATE, BUY_CLOSE_DATE
	, SELLER_ITEM_NO, TAX_TYPE, ITEM_MAKE_TYPE, WAREHOUSE_CODE
)
SELECT #{CMS_CATLG_ID}
     , NVL(MAX(P.CATLG_SEQ), 0) + 1
     , 'C'
     , #{st_user_id}
     , TO_CHAR(SYSDATE, 'YYYYMMDD')
     , TO_CHAR(SYSDATE, 'HH24MISS')
     , #{AGENT}
     , TO_NUMBER(NULLIF(#{BUY_PRICE},     ''))
     , #{PROCESS_TYPE}
     , #{DELIVERY_TYPE}
     , TO_NUMBER(NULLIF(#{DELIVERY_LT},   ''))
     , TO_NUMBER(NULLIF(#{MIN_ORDER_QTY}, ''))
     , TO_NUMBER(NULLIF(#{PUR_UNIT_QTY},  ''))
     , #{BUY_OPEN_DATE}
     , #{BUY_CLOSE_DATE}
     , #{SELLER_ITEM_NO}
     , #{TAX_TYPE}
     , #{ITEM_MAKE_TYPE}
     , #{WAREHOUSE_CODE}
  FROM CMSPRICE P
 WHERE P.CMS_CATLG_ID = #{CMS_CATLG_ID}
